    void buildDashboard(){
        LinearLayout nav=card();nav.addView(sectionHead("📊","داشبورد HSE"));
        LinearLayout stats=new LinearLayout(this);stats.setOrientation(LinearLayout.HORIZONTAL);for(int i=0;i<4;i++){TextView s=text("…",15,INK);s.setGravity(Gravity.CENTER);s.setTypeface(Typeface.DEFAULT_BOLD);s.setPadding(dp(5),dp(8),dp(5),dp(8));s.setBackground(box(Color.rgb(248,250,251),BORDER,dp(12)));stats.addView(s,new LinearLayout.LayoutParams(0,dp(70),1));if(i<3){Space sp=new Space(this);stats.addView(sp,new LinearLayout.LayoutParams(dp(7),1));}if(i==0)stats.setTag(s);}nav.addView(stats);statsView=(TextView)stats.getChildAt(0);
        TextView s2=(TextView)stats.getChildAt(2),s3=(TextView)stats.getChildAt(4),s4=(TextView)stats.getChildAt(6);statsView.setTag("منابع\n…");s2.setTag("یادداشت\n…");s3.setTag("ریسک بالا\n…");s4.setTag("رویداد باز\n…");
        // labels are updated by refreshAll
        gapIn(nav,10);LinearLayout q=new LinearLayout(this);q.setOrientation(LinearLayout.HORIZONTAL);Button b1=outline("📚 کتابخانه"),b2=outline("📝 یادداشت"),b3=outline("⚠️ ریسک"),b4=outline("🚨 حوادث");Button[] bs={b1,b2,b3,b4};for(int i=0;i<bs.length;i++){q.addView(bs[i],new LinearLayout.LayoutParams(0,dp(46),1));if(i<3)q.addView(new Space(this),new LinearLayout.LayoutParams(dp(5),1));}nav.addView(q);b1.setOnClickListener(v->jump(libraryView));b2.setOnClickListener(v->jump(notesView));b3.setOnClickListener(v->jump(riskView));b4.setOnClickListener(v->jump(incidentView));addCard(nav);
    }
    void jump(View v){if(v!=null)scroll.postDelayed(()->scroll.smoothScrollTo(0,Math.max(0,v.getTop()-dp(8))),80);}

    void buildLibrary(){
        LinearLayout c=card();libraryView=c;c.addView(sectionHead("📚","کتابخانه HSE"));c.addView(text("مدیریت منابع PDF، جست‌وجوی فارسی و جلوگیری از تکرار فایل",13,MUTED));gapIn(c,8);
        EditText q=input("مثلاً: کلاه ایمنی، ارزیابی ریسک، آتش‌سوزی...");c.addView(q);gapIn(c,8);LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);Button add=action("＋ افزودن PDF",BLUE),search=action("🔎 جست‌وجو",GREEN);row.addView(add,new LinearLayout.LayoutParams(0,dp(48),1));row.addView(new Space(this),new LinearLayout.LayoutParams(dp(8),1));row.addView(search,new LinearLayout.LayoutParams(0,dp(48),1));c.addView(row);TextView results=text("",13,INK);results.setPadding(0,dp(12),0,0);c.addView(results);add.setOnClickListener(v->pick(PICK_PDF,"application/pdf"));search.setOnClickListener(v->{String query=q.getText().toString().trim();if(query.isEmpty()){results.setText("عبارت جست‌وجو را وارد کنید.");return;}results.setText("در حال جست‌وجو…");io.execute(()->{try{ArrayList<LibraryDb.SearchHit> r=db.searchHits(query);StringBuilder sb=new StringBuilder();for(LibraryDb.SearchHit h:r)sb.append("📄 ").append(h.title).append(" — صفحه ").append(h.page).append(" — امتیاز ").append(h.score).append("\n").append(h.snippet).append("\n\n────────────\n\n");if(sb.length()>0)sb.setLength(sb.length()-16);String finalText=sb.length()==0?"نتیجه‌ای پیدا نشد.":sb.toString();runOnUiThread(()->{latestSearchText=finalText;results.setText(finalText);});}catch(Exception e){runOnUiThread(()->results.setText("خطا در جست‌وجو: "+safeMsg(e)));}});});
        gapIn(c,8);addExportTools(c,"نتایج آخرین جست‌وجو",()->latestSearchText.isEmpty()?"هنوز جست‌وجویی انجام نشده است.":latestSearchText);gapIn(c,10);buildRecommendedBooks(c);gapIn(c,12);c.addView(title("منابع واردشده",15));addExportTools(c,"کتابخانه HSE",()->exportDocuments());LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);c.addView(list);addCard(c);refreshDocuments(list);
    }
    void clearList(LinearLayout target,String message){target.removeAllViews();if(message!=null&&!message.isEmpty())target.addView(text(message,13,MUTED));}

    void refreshDocuments(LinearLayout target){io.execute(()->{try{ArrayList<LibraryDb.DocumentRow> rows=db.listDocuments();runOnUiThread(()->{target.removeAllViews();if(rows.isEmpty()){clearList(target,"هنوز PDFی وارد نشده است.");return;}for(LibraryDb.DocumentRow r:rows){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(0,dp(7),0,dp(7));TextView info=text("📄 "+r.title+"\n"+r.pages+" صفحه"+(r.category.isEmpty()?"":"  •  "+r.category),14,INK);Button del=outline("حذف");row.addView(info,new LinearLayout.LayoutParams(0,-2,1));row.addView(del,new LinearLayout.LayoutParams(dp(62),dp(42)));target.setGravity(Gravity.RIGHT);del.setOnClickListener(v->confirmDeleteDocument(r,target));target.addView(row);}});}catch(Exception e){runOnUiThread(()->clearList(target,"خطا در بارگذاری منابع"));}});}
    void confirmDeleteDocument(LibraryDb.DocumentRow r,LinearLayout target){new AlertDialog.Builder(this).setTitle("حذف منبع").setMessage("این PDF و اطلاعات صفحات آن حذف می‌شود:\n\n"+r.title).setNegativeButton("انصراف",null).setPositiveButton("حذف",(d,w)->io.execute(()->{try{db.deleteDocument(r.id);runOnUiThread(()->{toast("منبع حذف شد");refreshDocuments(target);refreshAll();});}catch(Exception e){runOnUiThread(()->toast("خطا در حذف: "+safeMsg(e)));}})).show();}


    void buildRecommendedBooks(LinearLayout c){
        c.addView(title("📚 ۱۰ مرجع منتخب ایمنی و HSE",15));
        c.addView(text("فهرست پیشنهادی فارسی؛ موارد دارای ترجمه فارسی انتخاب شده‌اند. متن کامل آثار دارای حق نشر داخل برنامه کپی نشده است؛ در صورت داشتن PDF مجاز، می‌توانید آن را با «افزودن PDF» وارد کنید.",12,MUTED));
        gapIn(c,7);
        LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);
        for(String[] b:RECOMMENDED_BOOKS){
            TextView item=text("📘 "+b[0]+"\n"+b[1]+"\nمترجم: "+b[2]+"\nحوزه: "+b[3],13,INK);
            item.setTextIsSelectable(true);item.setPadding(dp(10),dp(9),dp(10),dp(9));item.setBackground(box(Color.rgb(250,252,253),BORDER,dp(10)));list.addView(item,new LinearLayout.LayoutParams(-1,-2));gapIn(list,6);
        }
        c.addView(list);addExportTools(c,"۱۰ مرجع منتخب ایمنی",this::exportRecommendedBooks);
    }
    void changeFontScale(float delta){float next=Math.max(0.8f,Math.min(1.4f,fontScale+delta));if(Math.abs(next-fontScale)<0.01f)return;fontScale=next;getSharedPreferences("hse_ui",MODE_PRIVATE).edit().putFloat("font_scale",fontScale).apply();build();scroll.postDelayed(()->scroll.fullScroll(ScrollView.FOCUS_UP),50);toast("اندازه متن: "+Math.round(fontScale*100)+"٪");}

    void buildGlossary(){
        LinearLayout c=card();glossaryView=c;c.addView(sectionHead("📖","واژه‌ها و کلمات اختصاری HSE"));c.addView(text("واژه‌های پرکاربرد ایمنی، بهداشت، محیط‌زیست و مدیریت ریسک — کاملاً آفلاین",13,MUTED));gapIn(c,8);EditText q=input("جست‌وجو: PPE، LOTO، ارزیابی ریسک، مجوز کار...");c.addView(q);gapIn(c,8);TextView out=text("",13,INK);out.setGravity(Gravity.RIGHT|Gravity.TOP);out.setTextIsSelectable(true);c.addView(out);addExportTools(c,"واژه‌نامه HSE",()->exportGlossary());q.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){out.setText(filterGlossary(s.toString()));}public void afterTextChanged(android.text.Editable e){}});out.setText(filterGlossary(""));addCard(c);}
