    void buildRisk(){LinearLayout c=card();riskView=c;c.addView(sectionHead("⚠️","ارزیابی ریسک ۵×۵"));c.addView(text("احتمال × شدت = امتیاز؛ ۱–۴ کم، ۵–۱۱ متوسط، ۱۲–۱۹ زیاد، ۲۰–۲۵ بحرانی",13,MUTED));gapIn(c,8);EditText rh=input("خطر / فعالیت");c.addView(rh);gapIn(c,7);EditText rc=input("پیامد");c.addView(rc);gapIn(c,7);LinearLayout spinners=new LinearLayout(this);spinners.setOrientation(LinearLayout.HORIZONTAL);String[] vals={"1","2","3","4","5"};Spinner sl=new Spinner(this),ss=new Spinner(this);sl.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,vals));ss.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,vals));LinearLayout a=new LinearLayout(this),b=new LinearLayout(this);a.setOrientation(LinearLayout.VERTICAL);b.setOrientation(LinearLayout.VERTICAL);a.addView(text("احتمال",13,MUTED));a.addView(sl);b.addView(text("شدت",13,MUTED));b.addView(ss);spinners.addView(a,new LinearLayout.LayoutParams(0,-2,1));spinners.addView(new Space(this),new LinearLayout.LayoutParams(dp(8),1));spinners.addView(b,new LinearLayout.LayoutParams(0,-2,1));c.addView(spinners);gapIn(c,7);EditText ctrl=input("کنترل‌های موجود");c.addView(ctrl);gapIn(c,7);EditText ra=input("اقدام اصلاحی");c.addView(ra);gapIn(c,7);EditText rp=input("مسئول");c.addView(rp);gapIn(c,8);Button rs=action("✓ ثبت ارزیابی ریسک",ORANGE);c.addView(rs);LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);gapIn(c,8);c.addView(list);rs.setOnClickListener(v->{int lv=Integer.parseInt((String)sl.getSelectedItem()),sv=Integer.parseInt((String)ss.getSelectedItem()),score=lv*sv;String h=rh.getText().toString().trim();if(h.isEmpty()){toast("خطر یا فعالیت را وارد کنید");return;}rs.setEnabled(false);io.execute(()->{try{db.addRisk(h,rc.getText().toString().trim(),lv,sv,ctrl.getText().toString().trim(),ra.getText().toString().trim(),rp.getText().toString().trim());runOnUiThread(()->{rh.setText("");rc.setText("");ctrl.setText("");ra.setText("");rp.setText("");rs.setEnabled(true);toast("ریسک ثبت شد — امتیاز: "+score+" — "+riskLevel(score));refreshRisks(list);refreshAll();});}catch(Exception e){runOnUiThread(()->{rs.setEnabled(true);toast("خطا در ثبت ریسک: "+safeMsg(e));});}});});addCard(c);refreshRisks(list);}
